
CREATE TABLE IF NOT EXISTS nu_metal_list (
    id INT AUTO_INCREMENT PRIMARY KEY,
    band_name VARCHAR(255) NOT NULL,
    country VARCHAR(100),
    state VARCHAR(100),
    has_song VARCHAR(50),
    has_album VARCHAR(50),
    female_vocals VARCHAR(50),
    turntables VARCHAR(50),
    electronics VARCHAR(50),
    discogs_link TEXT,
    spotify_link TEXT,
    formed_year VARCHAR(50),
    live_status VARCHAR(100),
    nmp_status VARCHAR(100),
    for_fans_of TEXT,
    is_christian VARCHAR(50),
    additional_info TEXT
);

